(() => {
'use strict';

const $ = id => document.getElementById(id);
const esc = s => String(s ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const uid = () => (globalThis.crypto?.randomUUID ? crypto.randomUUID() : `g_${Date.now()}_${Math.random().toString(36).slice(2)}`);
const isoNow = () => new Date().toISOString();
const today = () => { const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
const clamp = (n,min,max) => Math.max(min,Math.min(max,n));
const num = (v,f=0) => Number.isFinite(Number(v)) ? Number(v) : f;
const SCHEMA_VERSION = 3;
const LEGACY_KEY = 'garang_v99_state_v2';
const DEMO_KEY = 'garang_demo_state_v3';
const SERVICES = window.GARANG_SERVICES || {};

const EMPTY = () => ({
  meta:{schemaVersion:SCHEMA_VERSION,createdAt:isoNow(),updatedAt:isoNow()},
  profile:null,
  onboarding:{complete:false,skipped:false,goal:'퍼포먼스 향상',experience:'intermediate',weeklyFrequency:4,availableMinutes:60,preferences:''},
  checkins:[], planner:[], workouts:[], meals:[], runs:[], body:[],
  memory:{entries:[],facts:[],preferences:[],goals:[],events:[]},
  actionLog:[], analytics:{events:[]}, errors:[], plan:'FREE'
});

let state = EMPTY();
let db = {exercise:[],food:[]};
let knowledge = [];
let firebaseReady=false, currentUser=null, currentPage='today';
let storageKey=DEMO_KEY, syncTimer=null, syncRetry=0;
let workoutDraft=[], mealDraft=[], mealScanDraft=null, runTimer=null, runState=null;
let currentCert={workout:null,running:null};
let progressRangeDays=30, memoryEditId=null;

function toast(msg){const t=$('toast');if(!t)return;t.textContent=msg;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),2600);}
function clone(x){return JSON.parse(JSON.stringify(x));}
function daysAgo(n){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-n);return d;}
function dateMs(s){const d=new Date(`${s||today()}T00:00:00`);return Number.isFinite(d.getTime())?d.getTime():0;}
function withinDays(s,n){return dateMs(s)>=daysAgo(Math.max(0,n-1)).getTime();}
function sum(a,fn){return a.reduce((x,y)=>x+fn(y),0);}
function uniqueDays(a){return new Set(a.map(x=>x.date).filter(Boolean)).size;}

function normalizeMeals(){
  state.meals=(Array.isArray(state.meals)?state.meals:[]).map(m=>{
    const items=Array.isArray(m.items)&&m.items.length?m.items.map(i=>({id:i.id||uid(),name:String(i.name||'음식'),grams:num(i.grams,100),kcal:num(i.kcal),protein:num(i.protein),carbs:num(i.carbs??i.carbohydrate),fat:num(i.fat)})):[{id:uid(),name:String(m.name||'음식'),grams:num(m.grams,100),kcal:num(m.kcal),protein:num(m.protein),carbs:num(m.carbs),fat:num(m.fat)}];
    const totals=items.reduce((a,i)=>({kcal:a.kcal+i.kcal,protein:a.protein+i.protein,carbs:a.carbs+i.carbs,fat:a.fat+i.fat}),{kcal:0,protein:0,carbs:0,fat:0});
    return {...m,id:m.id||uid(),date:m.date||today(),name:m.name||items.map(i=>i.name).slice(0,2).join(' + '),items,...totals};
  });
}
function migrateMemory(){
  state.memory=state.memory&&typeof state.memory==='object'?state.memory:{entries:[]};
  for(const k of ['facts','preferences','goals','events']) state.memory[k]=Array.isArray(state.memory[k])?state.memory[k]:[];
  state.memory.entries=Array.isArray(state.memory.entries)?state.memory.entries:[];
  if(!state.memory.entries.length){
    const add=(type,key,value,source='legacy')=>state.memory.entries.push({id:uid(),type,key,value:String(value?.text||value||''),source,confidence:.7,importance:2,userConfirmed:false,createdAt:value?.date?`${value.date}T00:00:00`:isoNow(),updatedAt:isoNow(),expiresAt:null});
    state.memory.facts.forEach((v,i)=>add('identity',`legacy_fact_${i}`,v));
    state.memory.preferences.forEach((v,i)=>add('preference',`legacy_preference_${i}`,v));
    state.memory.goals.forEach((v,i)=>add('goal',`legacy_goal_${i}`,v));
  }
}
function normalizeState(){
  const base=EMPTY(); state={...base,...(state||{})};
  state.meta={...base.meta,...(state.meta||{}),schemaVersion:SCHEMA_VERSION};
  for(const k of ['checkins','planner','workouts','meals','runs','body','actionLog','errors']) state[k]=Array.isArray(state[k])?state[k]:[];
  state.analytics=state.analytics&&typeof state.analytics==='object'?state.analytics:{events:[]};state.analytics.events=Array.isArray(state.analytics.events)?state.analytics.events:[];
  state.onboarding={...base.onboarding,...(state.onboarding||{})}; state.plan=state.plan==='PRO'?'PRO':'FREE';
  migrateMemory();normalizeMeals();
}
function touch(){state.meta.updatedAt=isoNow();state.meta.schemaVersion=SCHEMA_VERSION;}
function readLocal(key){try{const raw=localStorage.getItem(key);if(!raw)return null;return JSON.parse(raw);}catch(e){console.warn('local load failed',e);return null;}}
function writeLocal(){try{touch();localStorage.setItem(storageKey,JSON.stringify(state));return true;}catch(e){toast('기기 저장 공간을 확인해 주세요.');captureError('local_save',e);return false;}}
function loadLocal(key){const x=readLocal(key);state=x?{...EMPTY(),...x}:EMPTY();normalizeState();}
function saveState(opts={}){writeLocal();trackEvent(opts.event||'state_saved',{source:opts.source||'app'},false);if(firebaseReady&&currentUser)queueCloudSync();updateSyncUI();}

function setSync(s,msg){state.syncState=s;const b=$('syncBadge'),l=$('syncLabel');if(b)b.dataset.state=s;if(l)l.textContent=msg||({synced:'동기화됨',syncing:'동기화 중',pending:'동기화 대기',failed:'동기화 확인',local:'로컬 저장'}[s]||'저장');}
function updateSyncUI(){if(currentUser&&firebaseReady){if(!state.syncState)setSync('pending');else setSync(state.syncState);}else setSync('local','로컬 저장');}
function cloudRef(){return firebase.firestore().collection('users').doc(currentUser.uid).collection('app').doc('state');}
function cloudPayload(){
  const out=clone(state);delete out.syncState;
  out.workouts=out.workouts.slice(-350);out.meals=out.meals.slice(-350);out.body=out.body.slice(-250);out.checkins=out.checkins.slice(-180);out.planner=out.planner.slice(-300);out.actionLog=out.actionLog.slice(-300);out.errors=out.errors.slice(-80);out.analytics.events=out.analytics.events.slice(-400);
  out.runs=out.runs.slice(-200).map(r=>({...r,coords:Array.isArray(r.coords)?r.coords.slice(-250):[]}));
  out.memory.entries=out.memory.entries.slice(-400);out.memory.events=out.memory.events.slice(-300);
  return out;
}
async function cloudSaveNow(){
  if(!firebaseReady||!currentUser)return false;
  setSync('syncing');
  try{
    const payload=cloudPayload();payload.cloudUpdatedAt=firebase.firestore.FieldValue.serverTimestamp();payload.clientUpdatedAt=state.meta.updatedAt;
    await cloudRef().set(payload,{merge:false});
    syncRetry=0;state.syncState='synced';localStorage.setItem(`garang_last_sync_${currentUser.uid}`,isoNow());setSync('synced');return true;
  }catch(e){
    syncRetry++;state.syncState='failed';captureError('cloud_save',e);setSync(syncRetry<3?'pending':'failed',syncRetry<3?'동기화 재시도':'동기화 확인');
    if(syncRetry<3)setTimeout(()=>cloudSaveNow(),1200*Math.pow(2,syncRetry-1));return false;
  }
}
function queueCloudSync(){clearTimeout(syncTimer);state.syncState='pending';setSync('pending');syncTimer=setTimeout(()=>cloudSaveNow(),700);}
async function cloudLoadAndMerge(){
  if(!firebaseReady||!currentUser)return;
  setSync('syncing');
  try{
    let doc=await cloudRef().get();let remote=doc.exists?doc.data():null;
    if(!remote){const legacy=await firebase.firestore().collection('users').doc(currentUser.uid).get();if(legacy.exists&&legacy.data()?.profile)remote=legacy.data();}
    if(remote){
      const localUpdated=dateMs((state.meta?.updatedAt||'').slice(0,10))||new Date(state.meta?.updatedAt||0).getTime();
      const remoteUpdated=new Date(remote.clientUpdatedAt||remote.meta?.updatedAt||0).getTime();
      if(!readLocal(storageKey)||remoteUpdated>=localUpdated){state={...EMPTY(),...remote};normalizeState();writeLocal();}
      else await cloudSaveNow();
    }else if(readLocal(storageKey)){await cloudSaveNow();}
    state.syncState='synced';setSync('synced');render();
  }catch(e){state.syncState='failed';captureError('cloud_load',e);setSync('failed','동기화 확인');toast('클라우드 연결을 확인 중입니다. 기록은 기기에 안전하게 저장됩니다.');render();}
}

function captureError(type,e){try{state.errors=Array.isArray(state.errors)?state.errors:[];state.errors.push({id:uid(),type,message:String(e?.message||e||'unknown'),code:e?.code||null,at:isoNow()});if(state.errors.length>100)state.errors=state.errors.slice(-100);localStorage.setItem(storageKey,JSON.stringify(state));}catch{}}
function trackEvent(name,props={},persist=true){try{state.analytics.events.push({id:uid(),name,props,at:isoNow()});if(state.analytics.events.length>500)state.analytics.events=state.analytics.events.slice(-500);if(persist)writeLocal();if(SERVICES.analyticsEndpoint)fetch(SERVICES.analyticsEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,props,at:isoNow(),userId:currentUser?.uid||null})}).catch(()=>{});}catch{}}
window.addEventListener('error',e=>captureError('frontend_error',e.error||e.message));window.addEventListener('unhandledrejection',e=>captureError('unhandled_rejection',e.reason));

async function loadJSON(path){const r=await fetch(path,{cache:'no-store'});if(!r.ok)throw new Error(`${path} ${r.status}`);return r.json();}
async function loadJSONL(path){const r=await fetch(path,{cache:'no-store'});if(!r.ok)throw new Error(`${path} ${r.status}`);const text=await r.text();return text.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(x=>{try{return JSON.parse(x)}catch{return null}}).filter(Boolean);}
async function loadDB(){const r=await Promise.allSettled([loadJSON('exercise-db.json'),loadJSON('food-db.json'),loadJSONL('exercise_knowledge.jsonl'),loadJSONL('food_knowledge.jsonl'),loadJSONL('fitmind_rules.jsonl')]);if(r[0].status==='fulfilled')db.exercise=r[0].value;if(r[1].status==='fulfilled')db.food=r[1].value;knowledge=r.slice(2).filter(x=>x.status==='fulfilled').flatMap(x=>x.value).slice(0,1800);if(!db.exercise.length||!db.food.length)toast('운동/식단 데이터 일부를 불러오지 못했습니다.');}

function initFirebase(){
  try{
    const cfg=window.GARANG_FIREBASE_CONFIG;if(!cfg?.apiKey||!window.firebase?.apps){firebaseReady=false;return;}
    if(!firebase.apps.length)firebase.initializeApp(cfg);firebaseReady=!!firebase.apps.length;
    if(firebaseReady)firebase.auth().onAuthStateChanged(async u=>{
      currentUser=u;
      if(u){storageKey=`garang_user_${u.uid}_v3`;loadLocal(storageKey);await cloudLoadAndMerge();showApp();}
      else if(localStorage.getItem('garang_demo')==='1'){storageKey=DEMO_KEY;loadLocal(storageKey);showApp();}
      else showAuth();
    });
  }catch(e){firebaseReady=false;captureError('firebase_init',e);}
}
function showAuth(){$('authView').hidden=false;$('appView').hidden=true;}
function showApp(){$('authView').hidden=true;$('appView').hidden=false;$('planBadge').textContent=state.plan;updateSyncUI();if(!state.onboarding.complete&&!state.onboarding.skipped)currentPage='onboarding';render();}
function bindAuth(){
  document.querySelectorAll('[data-auth-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-auth-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('loginForm').hidden=b.dataset.authTab!=='login';$('signupForm').hidden=b.dataset.authTab!=='signup';});
  $('loginForm').onsubmit=async e=>{e.preventDefault();await emailAuth(false)};$('signupForm').onsubmit=async e=>{e.preventDefault();await emailAuth(true)};
  $('resetPassword').onclick=resetPassword;$('googleBtn').onclick=()=>socialAuth('google');$('appleBtn').onclick=()=>socialAuth('apple');
  $('demoBtn').onclick=()=>{localStorage.setItem('garang_demo','1');storageKey=DEMO_KEY;loadLocal(storageKey);state.profile=state.profile||{name:'GARANG 사용자',age:23,height:174,weight:67,goal:'퍼포먼스 향상'};saveState({event:'demo_started'});showApp();};
  $('logoutBtn').onclick=logout;$('profileTopBtn').onclick=()=>go('profile');$('syncBadge').onclick=()=>{if(currentUser&&firebaseReady){toast('클라우드 동기화를 다시 확인합니다.');cloudSaveNow().then(ok=>ok&&toast('동기화가 완료되었습니다.'));}else toast('로그인하면 Firebase와 동기화됩니다.');};
}
async function emailAuth(signup){if(!firebaseReady)return toast('Firebase 설정을 확인해 주세요.');try{const email=$(signup?'signupEmail':'loginEmail').value.trim(),pw=$(signup?'signupPassword':'loginPassword').value;if(signup){const c=await firebase.auth().createUserWithEmailAndPassword(email,pw);await c.user.updateProfile({displayName:email.split('@')[0]});trackEvent('signup_completed');}else await firebase.auth().signInWithEmailAndPassword(email,pw);toast(signup?'계정을 만들었습니다.':'로그인했습니다.');}catch(e){toast(firebaseError(e));}}
async function socialAuth(kind){if(!firebaseReady)return toast('Firebase 설정을 확인해 주세요.');try{const p=kind==='google'?new firebase.auth.GoogleAuthProvider():new firebase.auth.OAuthProvider('apple.com');await firebase.auth().signInWithPopup(p);}catch(e){toast(firebaseError(e));}}
async function resetPassword(){if(!firebaseReady)return toast('Firebase 설정을 확인해 주세요.');const email=$('loginEmail').value.trim();if(!email)return toast('이메일을 먼저 입력해 주세요.');try{await firebase.auth().sendPasswordResetEmail(email);toast('재설정 메일을 보냈습니다.');}catch(e){toast(firebaseError(e));}}
function firebaseError(e){const c=e?.code||'';const map={'auth/invalid-credential':'이메일 또는 비밀번호가 올바르지 않습니다.','auth/email-already-in-use':'이미 사용 중인 이메일입니다.','auth/weak-password':'비밀번호는 6자 이상이어야 합니다.','auth/popup-closed-by-user':'로그인이 취소되었습니다.','auth/operation-not-allowed':'Firebase Console에서 로그인 방식을 활성화해 주세요.','auth/unauthorized-domain':'Firebase 승인 도메인을 확인해 주세요.','auth/popup-blocked':'브라우저 팝업을 허용해 주세요.','permission-denied':'Firestore 권한 규칙을 확인해 주세요.'};return map[c]||e?.message||'인증 중 오류가 발생했습니다.';}
function logout(){if(firebaseReady&&currentUser)firebase.auth().signOut().catch(()=>{});localStorage.removeItem('garang_demo');currentUser=null;storageKey=DEMO_KEY;showAuth();}

function nav(){document.querySelectorAll('.bottom-nav button').forEach(b=>b.onclick=()=>go(b.dataset.page));}
function go(page){currentPage=page;render();window.scrollTo({top:0,behavior:'instant'});}
function render(){document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===currentPage));const m=$('main');const fn=pages[currentPage]||pages.today;m.innerHTML=fn();bindPage();updateSyncUI();}

function todayWorkouts(){return state.workouts.filter(x=>x.date===today());}
function dayMeals(date=today()){return state.meals.filter(x=>x.date===date);}
function totalsMeals(date=today()){return dayMeals(date).reduce((a,x)=>({kcal:a.kcal+num(x.kcal),protein:a.protein+num(x.protein),carbs:a.carbs+num(x.carbs),fat:a.fat+num(x.fat)}),{kcal:0,protein:0,carbs:0,fat:0});}
function latestCheckin(){return state.checkins.filter(x=>x.date===today()).at(-1)||null;}
function latestBody(){return state.body.slice().sort((a,b)=>dateMs(a.date)-dateMs(b.date)).at(-1)||null;}
function todayPlans(){return state.planner.filter(x=>x.date===today()).sort((a,b)=>String(a.time||'99:99').localeCompare(String(b.time||'99:99')));}
function workoutKcalToday(){return sum(todayWorkouts(),x=>num(x.kcal));}
function proteinTarget(){return Math.round(num(state.profile?.weight,67)*1.6);}

function performanceScore(){
  const c=latestCheckin(), sevenW=state.workouts.filter(x=>withinDays(x.date,7)), sevenR=state.runs.filter(x=>withinDays(x.date,7)), sevenM=state.meals.filter(x=>withinDays(x.date,7));
  const activityDays=uniqueDays([...sevenW,...sevenR]);const freq=Math.max(1,num(state.onboarding.weeklyFrequency,4));const consistency=clamp(Math.round(activityDays/freq*100),0,100);
  const mealDays=[...new Set(sevenM.map(x=>x.date))];const proteinScores=mealDays.map(d=>clamp(totalsMeals(d).protein/Math.max(1,proteinTarget())*100,0,100));const nutrition=proteinScores.length?Math.round(sum(proteinScores,x=>x)/proteinScores.length):null;
  const readiness=c?clamp(Math.round((clamp(num(c.sleep,7)/8,0,1.2)*30)+(num(c.energy,3)/5*30)+((6-num(c.stress,3))/5*20)+((6-num(c.soreness,2))/5*20)),0,100):null;
  const body=state.body.length>=2?75:state.body.length?65:null;
  const vals=[consistency,nutrition,readiness,body].filter(v=>v!==null);const dataCount=sevenW.length+sevenR.length+sevenM.length+state.body.length+(c?1:0);
  if(!dataCount)return {total:null,components:{Consistency:null,Nutrition:null,Recovery:null,Body:null},reasons:['기록이 쌓이면 GARANG Score가 생성됩니다.']};
  const total=Math.round(sum(vals,x=>x)/vals.length);const reasons=[];
  if(readiness!==null&&readiness<60)reasons.push('오늘 회복 상태가 전체 점수를 낮추고 있습니다.');
  if(consistency<60)reasons.push('최근 7일 운동 일관성을 높일 여지가 있습니다.');
  if(nutrition!==null&&nutrition<70)reasons.push('최근 단백질 목표 달성률이 낮습니다.');
  if(!reasons.length)reasons.push('최근 기록이 안정적으로 유지되고 있습니다.');
  return {total,components:{Consistency:consistency,Nutrition:nutrition,Recovery:readiness,Body:body},reasons};
}
function coachDecision(){
  const c=latestCheckin();const recentW=state.workouts.filter(x=>withinDays(x.date,3));const recentR=state.runs.filter(x=>withinDays(x.date,3));const available=num(c?.availableMinutes,state.onboarding.availableMinutes||60);let readiness=null;
  if(c)readiness=clamp(Math.round((num(c.sleep,7)/8*30)+(num(c.energy,3)/5*30)+((6-num(c.stress,3))/5*20)+((6-num(c.soreness,2))/5*20)),0,100);
  let decision='KEEP',title=`${available}분 기본 훈련`,summary='현재 기록 기준으로 계획을 유지해도 좋습니다.',reasons=[],confidence=.58;
  if(!c){reasons.push('오늘 컨디션 체크인이 없어 최근 기록 중심으로 판단했습니다.');confidence=.46;}
  else {reasons.push(`수면 ${num(c.sleep).toFixed(1)}시간 · 에너지 ${c.energy}/5 · 스트레스 ${c.stress}/5`);confidence=.82;}
  if(c&&num(c.sleep)<4.5){decision='REST';title='회복 우선';summary='수면 부족이 커서 고강도 훈련보다 회복을 우선합니다.';reasons.push('수면이 4.5시간 미만입니다.');}
  else if(c&&readiness<45){decision='RECOVER';title=`${Math.min(30,available)}분 회복 세션`;summary='오늘은 강도를 낮추고 움직임과 회복에 집중하는 편이 좋습니다.';reasons.push(`회복 지표가 ${readiness}점으로 낮습니다.`);}
  else if(c&&num(c.soreness)>=4){decision='REPLACE';title=`${Math.min(40,available)}분 대체 세션`;summary='근육통이 높은 부위를 피하고 다른 부위 또는 Zone 2로 대체합니다.';reasons.push(`근육통 ${c.soreness}/5${c.soreArea?` · ${c.soreArea}`:''}`);}
  else if(recentW.length>=3&&(!c||readiness<68)){decision='REDUCE';title=`${Math.min(45,available)}분 감량 세션`;summary='최근 훈련량을 고려해 오늘 총 볼륨을 약 20% 낮춥니다.';reasons.push(`최근 3일 운동 기록 ${recentW.length}개가 있습니다.`);}
  else {if(recentW.length)reasons.push(`최근 3일 운동 기록 ${recentW.length}개를 반영했습니다.`);if(recentR.length)reasons.push(`최근 러닝 ${recentR.length}회를 함께 반영했습니다.`);}
  const plan=todayPlans()[0];if(plan)reasons.push(`오늘 Planner의 “${plan.title}” 일정과 함께 판단했습니다.`);
  return {decision,title,summary,reasons:reasons.slice(0,4),confidence,readiness,available};
}
function weeklyReview(){const w=state.workouts.filter(x=>withinDays(x.date,7)),r=state.runs.filter(x=>withinDays(x.date,7)),m=state.meals.filter(x=>withinDays(x.date,7)),p=state.planner.filter(x=>withinDays(x.date,7));const completed=p.filter(x=>x.completed).length;return {sessions:uniqueDays(w),volume:Math.round(sum(w,x=>num(x.volume))),runKm:sum(r,x=>num(x.distance)),protein:uniqueDays(m)?Math.round(sum([...new Set(m.map(x=>x.date))],d=>totalsMeals(d).protein)/uniqueDays(m)):0,planRate:p.length?Math.round(completed/p.length*100):0};}

function pageHead(kicker,title,desc='',action=''){return `<div class="page-head"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1>${desc?`<p class="muted">${desc}</p>`:''}</div>${action}</div>`;}
function todayPage(){
  const score=performanceScore(),dec=coachDecision(),t=totalsMeals(),body=latestBody(),ci=latestCheckin(),plans=todayPlans();const scoreText=score.total??'—';
  return `${pageHead('TODAY / 오늘','오늘의 선택',`${esc(state.profile?.name||'사용자')}님의 기록을 필요한 만큼만 보여줍니다.`,`<button class="ghost" data-pagego="profile">프로필</button>`)}
  <section class="card today-hero"><div class="hero-top"><div class="hero-copy"><span class="eyebrow">GARANG DECISION · ${dec.decision}</span><h2>${esc(dec.title)}</h2><p>${esc(dec.summary)}</p><div class="hero-actions"><button class="primary" data-action="apply-coach-plan">오늘 계획에 적용</button><button class="ghost" data-pagego="coach">이유 보기</button></div></div><div class="score-orb" style="--score:${score.total||0}"><div><strong>${scoreText}</strong><span>GARANG SCORE</span></div></div></div>
  <div class="today-strip"><div><strong>${todayWorkouts().length}</strong><span>오늘 운동 기록</span></div><div><strong>${Math.round(t.protein)}g</strong><span>단백질 / ${proteinTarget()}g</span></div><div><strong>${Math.round(t.kcal)}</strong><span>섭취 kcal</span></div><div><strong>${body?.weight?`${body.weight}kg`:state.profile?.weight?`${state.profile.weight}kg`:'—'}</strong><span>최근 체중</span></div></div></section>
  <div class="section-title"><h2>오늘의 상태</h2><span class="pill ${ci?'jade':''}">${ci?'저장됨':'체크인 필요'}</span></div>
  <section class="card checkin-compact"><div><h3>${ci?`회복 ${dec.readiness??'—'} / 100`:'30초 체크인'}</h3><div class="checkin-summary">${ci?`<span class="pill">수면 ${ci.sleep}h</span><span class="pill">에너지 ${ci.energy}/5</span><span class="pill">스트레스 ${ci.stress}/5</span><span class="pill">근육통 ${ci.soreness}/5</span>`:`<span class="muted">원본 수치는 홈에 늘어놓지 않고 판단에만 사용합니다.</span>`}</div></div><button class="ghost" data-action="open-checkin">${ci?'수정':'상태 저장'}</button></section>
  <div class="section-title"><h2>오늘 일정</h2><button class="text-btn" data-pagego="planner">전체 보기</button></div>
  <section class="card">${plans.length?plans.slice(0,3).map(planRow).join(''):`<div class="empty">아직 일정이 없습니다.<br>GARANG의 추천을 계획에 적용하거나 직접 추가해 보세요.</div>`}</section>
  <div class="section-title"><h2>빠른 기록</h2></div><div class="log-hub"><button class="card hub-card" data-pagego="workout"><span class="hub-icon">○</span><h3>운동</h3><p>세트·반복·중량·RPE</p></button><button class="card hub-card" data-pagego="nutrition"><span class="hub-icon">◌</span><h3>식단</h3><p>사진 초안·영양성분 기록</p></button></div>`;
}
function coachPage(){const d=coachDecision(),s=performanceScore();return `${pageHead('COACH / 가랑 지능','GARANG Coach','기록을 읽고 유지·감량·대체·회복·휴식 중 오늘의 방향을 결정합니다.')}
<div class="coach-layout"><section class="card coach-panel"><div class="coach-answer" id="aiAnswer">${esc(localCoachSummary(d,s))}</div><div class="coach-input"><div class="field"><label>GARANG에게 질문</label><textarea id="aiQuestion" placeholder="예: 오늘 운동을 그대로 해도 될까?"></textarea></div><div class="actions" style="margin-top:10px"><button id="askAI" class="primary">분석 요청</button><button class="ghost" data-q="오늘 운동 강도를 정해줘">오늘 강도</button><button class="ghost" data-q="오늘 식단을 분석해줘">식단</button></div><div class="helper">외부 LLM이 연결되면 n8n/AI Gateway를 사용합니다. 미연결 시 GARANG Coach Engine V1의 규칙 기반 분석임을 명확히 표시합니다.</div></div></section>
<aside class="grid"><section class="card decision-card"><span class="decision-label">TODAY DECISION</span><div class="decision-value">${d.decision}</div><p class="muted">${esc(d.summary)}</p><div class="reason-list">${d.reasons.map(x=>`<div class="reason-item">${esc(x)}</div>`).join('')}</div><div class="metric-row"><span>Confidence</span><b>${Math.round(d.confidence*100)}%</b></div><button class="primary wide" data-action="apply-coach-plan">Planner에 적용</button></section>
<section class="card"><h3>사용 중인 Context</h3><div class="metric-row"><span>Workout</span><b>${state.workouts.length}</b></div><div class="metric-row"><span>Nutrition</span><b>${state.meals.length}</b></div><div class="metric-row"><span>Running</span><b>${state.runs.length}</b></div><div class="metric-row"><span>Body</span><b>${state.body.length}</b></div><div class="metric-row"><span>Memory V2</span><b>${state.memory.entries.length}</b></div></section></aside></div>`;}
function logPage(){return `${pageHead('LOG / 기록','기록','입력은 한곳에 모으고, 분석은 PROGRESS에서 분리합니다.')}
<div class="log-hub"><button class="card hub-card" data-pagego="workout"><span class="hub-icon">○</span><h3>Workout</h3><p>세트·반복·중량·RPE·볼륨</p></button><button class="card hub-card" data-pagego="nutrition"><span class="hub-icon">◌</span><h3>Nutrition</h3><p>Meal Scan 초안·DB 영양정보</p></button><button class="card hub-card" data-pagego="running"><span class="hub-icon">⌁</span><h3>Running</h3><p>GPS·거리·페이스·기록</p></button><button class="card hub-card" data-pagego="body"><span class="hub-icon">◇</span><h3>Body</h3><p>체중·골격근·체지방·BMI/BMR</p></button></div><div class="section-title"><h2>실행 레이어</h2></div><div class="grid grid-2"><button class="card hub-card" data-pagego="planner"><span class="hub-icon">▦</span><h3>Planner</h3><p>AI 추천과 사용자 확정 계획을 구분합니다.</p></button><button class="card hub-card" data-pagego="memory"><span class="hub-icon">✧</span><h3>Memory</h3><p>장기 목표·선호·습관을 구조화합니다.</p></button></div>`;}
function workoutPage(){return `${pageHead('LOG / WORKOUT','운동 기록','기존 세션 기록 기능을 유지하면서 입력 밀도를 정리했습니다.')}
<div class="grid grid-2"><section class="card"><h3>운동 추가</h3><div class="form-grid"><div class="field full"><label>운동</label><input id="wName" list="exerciseList" placeholder="바벨 벤치프레스"><datalist id="exerciseList">${db.exercise.slice(0,700).map(x=>`<option value="${esc(x.exercise_name)}">`).join('')}</datalist></div><div class="field"><label>세트</label><input id="wSets" type="number" min="1" value="3"></div><div class="field"><label>반복</label><input id="wReps" type="number" min="1" value="10"></div><div class="field"><label>중량 kg</label><input id="wWeight" type="number" min="0" step="0.5" value="60"></div><div class="field"><label>RPE</label><input id="wRpe" type="number" min="1" max="10" step="0.5" value="8"></div><div class="field"><label>시간 분</label><input id="wDuration" type="number" min="1" value="15"></div><div class="field"><label>체중 kg</label><input id="wBody" type="number" min="1" step="0.1" value="${state.profile?.weight||67}"></div></div><div class="actions" style="margin-top:12px"><button id="addWorkout" class="primary">세션에 추가</button><button id="clearWorkoutDraft" class="ghost">초기화</button></div><div id="workoutDraftArea" class="draft-area" style="margin-top:14px">${renderWorkoutDraft()}</div><div class="session-total"><div><span>총 소모</span><strong>${Math.round(sum(workoutDraft,x=>x.kcal))} kcal</strong></div><div><span>총 볼륨</span><strong>${Math.round(sum(workoutDraft,x=>x.volume)).toLocaleString()} kg</strong></div></div><button id="saveWorkoutSession" class="primary wide" style="margin-top:12px" ${workoutDraft.length?'':'disabled'}>운동 세션 저장</button></section>
<section class="card"><h3>GARANG Verified</h3><p class="muted">기존 운동 인증 미디어 기능을 유지했습니다.</p><button id="certWorkout" class="ghost">사진/영상 선택</button><div id="workoutCertArea" class="empty" style="margin-top:12px">선택한 미디어가 없습니다.</div></section></div>
<div class="section-title"><h2>최근 운동</h2><span class="pill">오늘 ${Math.round(workoutKcalToday())} kcal</span></div><section class="card"><div class="list">${state.workouts.slice().reverse().slice(0,30).map(w=>`<div class="list-item"><div><strong>${esc(w.name)}</strong><div class="muted">${w.date} · ${w.sets}×${w.reps} · ${w.weight}kg · RPE ${w.rpe}</div></div><span class="pill">${Math.round(w.volume||0)}kg</span></div>`).join('')||'<div class="empty">운동 기록이 없습니다.</div>'}</div></section>`;}
function renderWorkoutDraft(){return workoutDraft.length?`<div class="list">${workoutDraft.map((x,i)=>`<div class="list-item"><div><strong>${esc(x.name)}</strong><div class="muted">${x.sets}×${x.reps} · ${x.weight}kg · RPE ${x.rpe} · 약 ${Math.round(x.kcal)} kcal</div></div><div class="actions"><button class="ghost small" data-edit-workout="${i}">수정</button><button class="ghost small" data-remove-workout="${i}">삭제</button></div></div>`).join('')}</div>`:'<div class="empty">운동을 추가하면 세션 초안이 여기에 표시됩니다.</div>';}
function nutritionPage(){const t=totalsMeals();const scan=mealScanDraft;return `${pageHead('LOG / NUTRITION','식단','사진을 먼저 선택하고, 인식 결과는 반드시 사용자가 확인한 뒤 저장합니다.')}
<section class="card meal-scan"><div class="section-title" style="margin-top:0"><h2>Meal Scan</h2><span class="pill ${SERVICES.mealScanEndpoint?'jade':'red'}">${SERVICES.mealScanEndpoint?'VISION CONNECTED':'DEV FOUNDATION'}</span></div><div class="scan-preview">${scan?.url?`<img src="${scan.url}" alt="식사 사진 미리보기">`:`<div class="scan-placeholder">사진을 선택하면<br>미리보기가 표시됩니다.</div>`}<div><p class="scan-status">${SERVICES.mealScanEndpoint?'Vision API로 음식 후보와 영양성분 초안을 생성합니다. 자동 저장하지 않습니다.':'Vision API는 아직 연결되지 않았습니다. 현재는 사진 UI와 확인 플로우를 검증하고, 음식명 입력 시 내장 Food DB로 영양 초안을 생성합니다.'}</p><div class="actions"><button id="pickMealScan" class="primary">음식 사진 선택</button><button id="clearMealScan" class="ghost">초기화</button></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>음식명 / 보정</label><input id="scanFoodName" value="${esc(scan?.manualName||'')}" placeholder="예: 닭가슴살 샐러드"></div><div class="field"><label>예상 중량 g</label><input id="scanFoodGram" type="number" min="1" value="${scan?.grams||100}"></div></div><button id="analyzeMealScan" class="ghost wide" style="margin-top:10px">분석 초안 만들기</button>${scan?.items?.length?`<div class="list" style="margin-top:12px">${scan.items.map(i=>`<div class="list-item"><div><strong>${esc(i.name)}</strong><div class="muted">${i.grams}g · ${Math.round(i.kcal)} kcal · P ${Math.round(i.protein)}g · C ${Math.round(i.carbs)}g · F ${Math.round(i.fat)}g</div></div></div>`).join('')}</div><button id="confirmMealScan" class="primary wide" style="margin-top:10px">초안을 식사에 추가</button>`:''}</div></div></section>
<div class="grid grid-2" style="margin-top:13px"><section class="card"><h3>직접 음식 추가</h3><div class="field"><label>음식/메뉴</label><input id="foodSearch" list="foodList" placeholder="닭가슴살"><datalist id="foodList">${db.food.slice(0,1500).map(x=>`<option value="${esc(x.name)}">`).join('')}</datalist></div><div class="form-grid" style="margin-top:10px"><div class="field"><label>섭취량 g</label><input id="foodGram" type="number" min="1" value="100"></div><div class="field"><label>kcal</label><input id="foodKcal" type="number" value="0"></div><div class="field"><label>단백질 g</label><input id="foodProtein" type="number" value="0"></div><div class="field"><label>탄수화물 g</label><input id="foodCarb" type="number" value="0"></div><div class="field"><label>지방 g</label><input id="foodFat" type="number" value="0"></div></div><div class="actions" style="margin-top:10px"><button id="fillFood" class="ghost">DB 불러오기</button><button id="addFood" class="primary">추가</button></div><div id="mealDraftArea" class="draft-area" style="margin-top:12px">${renderMealDraft()}</div><div class="session-total"><div><span>끼니 총 kcal</span><strong>${Math.round(sum(mealDraft,x=>x.kcal))}</strong></div><div><span>P / C / F</span><strong>${Math.round(sum(mealDraft,x=>x.protein))} / ${Math.round(sum(mealDraft,x=>x.carbs))} / ${Math.round(sum(mealDraft,x=>x.fat))}</strong></div></div><button id="saveMeal" class="primary wide" style="margin-top:10px" ${mealDraft.length?'':'disabled'}>한 끼 저장</button></section>
<section class="card"><h3>오늘 누적</h3><div class="grid grid-2"><div><div class="stat">${Math.round(t.kcal)}</div><div class="stat-label">kcal</div></div><div><div class="stat">${Math.round(t.protein)}g</div><div class="stat-label">단백질 / ${proteinTarget()}g</div></div><div><div class="stat">${Math.round(t.carbs)}g</div><div class="stat-label">탄수화물</div></div><div><div class="stat">${Math.round(t.fat)}g</div><div class="stat-label">지방</div></div></div></section></div>
<div class="section-title"><h2>오늘 식사</h2></div><section class="card"><div class="list">${dayMeals().slice().reverse().map(x=>`<div class="meal-card"><div class="metric-row"><strong>${esc(x.name)}</strong><b>${Math.round(x.kcal)} kcal</b></div><div class="meal-items">${x.items.map(i=>`<span>${esc(i.name)} ${i.grams}g</span>`).join('')}</div><div class="muted">P ${Math.round(x.protein)}g · C ${Math.round(x.carbs)}g · F ${Math.round(x.fat)}g</div></div>`).join('')||'<div class="empty">오늘 식사 기록이 없습니다.</div>'}</div></section>`;}
function renderMealDraft(){return mealDraft.length?`<div class="list">${mealDraft.map((x,i)=>`<div class="list-item"><div><strong>${esc(x.name)}</strong><div class="muted">${x.grams}g · ${Math.round(x.kcal)} kcal · P ${Math.round(x.protein)}g</div></div><div class="actions"><button class="ghost small" data-edit-food="${i}">수정</button><button class="ghost small" data-remove-food="${i}">삭제</button></div></div>`).join('')}</div>`:'<div class="empty">음식 또는 Meal Scan 초안을 추가하세요.</div>';}
function runningPage(){return `${pageHead('LOG / RUNNING','러닝','GPS 기반 거리·시간·페이스를 기록합니다.')}
<div class="grid grid-2"><section class="card"><div class="grid grid-3"><div><div class="stat" id="runDistance">0.00</div><div class="stat-label">km</div></div><div><div class="stat" id="runTime">00:00</div><div class="stat-label">시간</div></div><div><div class="stat" id="runPace">—</div><div class="stat-label">분/km</div></div></div><div class="map-box" style="margin-top:16px"><div class="map-grid"></div><svg class="route" viewBox="0 0 100 100" preserveAspectRatio="none"><polyline id="routeLine" points=""></polyline></svg><div class="map-note" id="gpsStatus">GPS 대기 중</div></div><div class="actions" style="margin-top:12px"><button id="runStart" class="primary">러닝 시작</button><button id="runStop" class="ghost">정지 & 저장</button><button id="runCert" class="ghost">인증 미디어</button></div></section><section class="card"><h3>러닝 인증</h3><div id="runCertArea" class="empty">미디어를 선택하면 인증 오버레이를 생성합니다.</div></section></div>
<div class="section-title"><h2>최근 기록</h2></div><section class="card"><div class="list">${state.runs.slice().reverse().slice(0,30).map(x=>`<div class="list-item"><div><strong>${num(x.distance).toFixed(2)} km</strong><div class="muted">${x.date} · ${num(x.duration).toFixed(1)}분 · ${x.pace||'—'} /km</div></div><span class="pill">${Math.round(x.kcal||0)} kcal</span></div>`).join('')||'<div class="empty">러닝 기록이 없습니다.</div>'}</div></section>`;}
function bodyPage(){const b=latestBody();return `${pageHead('LOG / BODY','Body Intelligence','측정값은 직접 확인한 뒤 저장하며 단일 값보다 추세를 우선합니다.')}
<div class="grid grid-2"><section class="card"><h3>체성분 입력</h3><div class="form-grid"><div class="field"><label>측정일</label><input id="bDate" type="date" value="${today()}"></div><div class="field"><label>체중 kg</label><input id="bWeight" type="number" step="0.1" value="${b?.weight||state.profile?.weight||''}"></div><div class="field"><label>골격근량 kg</label><input id="bMuscle" type="number" step="0.1" value=""></div><div class="field"><label>체지방률 %</label><input id="bFatPct" type="number" step="0.1" value=""></div><div class="field"><label>체지방량 kg</label><input id="bFatMass" type="number" step="0.1" value=""></div><div class="field"><label>키 cm</label><input id="bHeight" type="number" step="0.1" value="${state.profile?.height||''}"></div></div><button id="saveBody" class="primary wide" style="margin-top:12px">체성분 저장</button><div class="helper">BMI/BMR은 입력값을 바탕으로 계산해 저장합니다. OCR은 사용자 확인 후 저장하는 구조로 연결할 예정입니다.</div></section>
<section class="card"><h3>최근 상태</h3>${b?`<div class="metric-row"><span>체중</span><b>${b.weight||'—'} kg</b></div><div class="metric-row"><span>골격근량</span><b>${b.muscle||'—'} kg</b></div><div class="metric-row"><span>체지방률</span><b>${b.fatPercent||'—'} %</b></div><div class="metric-row"><span>BMI</span><b>${b.bmi||'—'}</b></div><div class="metric-row"><span>BMR</span><b>${b.bmr||'—'} kcal</b></div>`:'<div class="empty">체성분 기록이 없습니다.</div>'}</section></div>
<div class="section-title"><h2>기록</h2></div><section class="card"><div class="list">${state.body.slice().reverse().slice(0,30).map(x=>`<div class="list-item"><div><strong>${x.date}</strong><div class="muted">체중 ${x.weight||'—'}kg · 근육 ${x.muscle||'—'}kg · 체지방 ${x.fatPercent||'—'}%</div></div><span class="pill">BMI ${x.bmi||'—'}</span></div>`).join('')||'<div class="empty">기록이 없습니다.</div>'}</div></section>`;}
function progressPage(){const score=performanceScore(),r=weeklyReview(),data=filterProgress(progressRangeDays);const bestWeight=data.workouts.length?Math.max(...data.workouts.map(x=>num(x.weight))):0,bestVolume=data.workouts.length?Math.max(...data.workouts.map(x=>num(x.volume))):0,bestRun=data.runs.length?Math.max(...data.runs.map(x=>num(x.distance))):0;const bodyPts=data.body.map(x=>num(x.weight)).filter(Boolean);return `${pageHead('PROGRESS / 흐름','진행 상황','기록을 쌓는 화면과 해석하는 화면을 분리했습니다.')}
<div class="progress-tabs">${[[7,'7일'],[30,'30일'],[90,'3개월'],[365,'1년']].map(([d,l])=>`<button data-range="${d}" class="${progressRangeDays===d?'active':''}">${l}</button>`).join('')}</div>
<div class="grid grid-4" style="margin-top:12px"><section class="card"><div class="stat big">${score.total??'—'}</div><div class="stat-label">GARANG SCORE</div></section><section class="card"><div class="stat">${bestWeight||'—'}</div><div class="stat-label">최고 중량 kg</div></section><section class="card"><div class="stat">${bestVolume?Math.round(bestVolume).toLocaleString():'—'}</div><div class="stat-label">최고 볼륨 kg</div></section><section class="card"><div class="stat">${bestRun?bestRun.toFixed(1):'—'}</div><div class="stat-label">최장 러닝 km</div></section></div>
<div class="section-title"><h2>Score 구성</h2></div><div class="grid grid-2"><section class="card">${Object.entries(score.components).map(([k,v])=>`<div class="metric-row"><span>${k}</span><b>${v??'—'}</b></div>`).join('')}<div class="helper">${score.reasons.map(esc).join(' · ')}</div></section><section class="card"><h3>체중 추세</h3>${bodyPts.length>=2?sparkline(bodyPts):'<div class="empty">기간 내 체중 기록이 2개 이상 필요합니다.</div>'}</section></div>
<div class="section-title"><h2>Weekly Review</h2><span class="pill">최근 7일</span></div><section class="card"><div class="review-grid"><div class="review-cell"><strong>${r.sessions}</strong><span>운동 일수</span></div><div class="review-cell"><strong>${r.volume.toLocaleString()}</strong><span>총 볼륨 kg</span></div><div class="review-cell"><strong>${r.runKm.toFixed(1)}</strong><span>러닝 km</span></div><div class="review-cell"><strong>${r.protein}g</strong><span>평균 단백질</span></div><div class="review-cell"><strong>${r.planRate}%</strong><span>계획 수행률</span></div></div></section>`;}
function plannerPage(){return `${pageHead('PLANNER / 실행','Planner','AI 추천과 사용자 확정 계획을 구분하고 변경 이력을 남깁니다.')}
<div class="grid grid-2"><section class="card"><h3>계획 추가</h3><div class="form-grid"><div class="field"><label>날짜</label><input id="planDate" type="date" value="${today()}"></div><div class="field"><label>시간</label><input id="planTime" type="time" value="18:30"></div><div class="field"><label>종류</label><select id="planType"><option value="workout">운동</option><option value="running">러닝</option><option value="nutrition">식단</option><option value="recovery">회복</option></select></div><div class="field full"><label>계획</label><input id="planTitle" placeholder="예: 상체 45분"></div></div><button id="addPlan" class="primary wide" style="margin-top:12px">계획 저장</button></section><section class="card"><h3>Agent Write 원칙</h3><p class="muted">GARANG이 제안한 변경은 사용자가 승인한 경우에만 실제 Planner에 반영합니다.</p><button class="ghost wide" data-action="apply-coach-plan">오늘 Coach 추천 적용</button></section></div>
<div class="section-title"><h2>계획 목록</h2></div><section class="card">${state.planner.slice().sort((a,b)=>`${a.date}${a.time}`.localeCompare(`${b.date}${b.time}`)).map(planRow).join('')||'<div class="empty">계획이 없습니다.</div>'}</section>`;}
function planRow(p){return `<div class="plan-row"><div class="plan-time">${esc(p.time||'—')}</div><div><div class="plan-title">${esc(p.title)}</div><div class="plan-meta">${p.date} · ${esc(p.type||'plan')} · ${p.source==='ai'?'<span class="pill violet">AI Suggested</span>':'<span class="pill">User</span>'} ${p.completed?'<span class="pill jade">Completed</span>':''}</div></div><div class="actions plan-actions"><button class="ghost small" data-plan-toggle="${p.id}">${p.completed?'되돌리기':'완료'}</button><button class="ghost small" data-plan-delete="${p.id}">삭제</button></div></div>`;}
function memoryPage(){const entries=state.memory.entries.slice().sort((a,b)=>num(b.importance)-num(a.importance));return `${pageHead('MEMORY / 장기 기억','Memory V2','단순 채팅 로그가 아니라 출처·신뢰도·중요도·확인 상태를 가진 구조화된 기억입니다.')}
<div class="grid grid-2"><section class="card"><h3>${memoryEditId?'Memory 수정':'Memory 추가'}</h3><div class="form-grid"><div class="field"><label>유형</label><select id="memType"><option value="goal">Goal</option><option value="preference">Preference</option><option value="behavior">Behavior</option><option value="body">Body</option><option value="schedule">Schedule</option><option value="coaching_insight">Coaching Insight</option><option value="user_note">User Note</option></select></div><div class="field"><label>중요도 1~5</label><input id="memImportance" type="number" min="1" max="5" value="3"></div><div class="field full"><label>Key</label><input id="memKey" placeholder="예: preferred_training_time"></div><div class="field full"><label>내용</label><textarea id="memValue" rows="4" placeholder="예: 저녁 7시 이후 운동을 선호한다"></textarea></div></div><div class="actions" style="margin-top:10px"><button id="saveMemory" class="primary">저장</button>${memoryEditId?'<button id="cancelMemoryEdit" class="ghost">취소</button>':''}</div></section><section class="card"><h3>Memory 기준</h3><p class="muted">운동 기록 자체는 Workout 데이터입니다. 반복 선호·장기 목표·생활 습관처럼 미래 판단에 재사용할 가치가 있는 정보만 Memory로 저장합니다.</p><div class="metric-row"><span>전체 Memory</span><b>${entries.length}</b></div><div class="metric-row"><span>사용자 확인</span><b>${entries.filter(x=>x.userConfirmed).length}</b></div></section></div>
<div class="section-title"><h2>기억 중인 내용</h2></div><div class="grid grid-2">${entries.map(m=>`<section class="card memory-card"><div class="memory-meta"><span class="pill">${esc(m.type)}</span><span class="pill">importance ${m.importance}</span>${m.userConfirmed?'<span class="pill jade">confirmed</span>':'<span class="pill violet">AI/user draft</span>'}</div><strong>${esc(m.key)}</strong><div class="memory-value">${esc(m.value)}</div><div class="muted">source ${esc(m.source||'user')} · confidence ${Math.round(num(m.confidence,.8)*100)}%</div><div class="memory-actions"><button class="ghost" data-memory-confirm="${m.id}">${m.userConfirmed?'확인 취소':'사용자 확인'}</button><button class="ghost" data-memory-edit="${m.id}">수정</button><button class="ghost" data-memory-delete="${m.id}">삭제</button></div></section>`).join('')||'<div class="empty">저장된 Memory가 없습니다.</div>'}</div>`;}
function profilePage(){return `${pageHead('PROFILE / 설정','프로필 & 설정','사용자 모델, 데이터, 동기화 상태를 관리합니다.')}
<div class="grid grid-2"><section class="card"><h3>기본 프로필</h3><div class="form-grid"><div class="field"><label>이름</label><input id="pName" value="${esc(state.profile?.name||'')}"></div><div class="field"><label>나이</label><input id="pAge" type="number" value="${state.profile?.age||''}"></div><div class="field"><label>키 cm</label><input id="pHeight" type="number" value="${state.profile?.height||''}"></div><div class="field"><label>체중 kg</label><input id="pWeight" type="number" step="0.1" value="${state.profile?.weight||''}"></div><div class="field full"><label>목표</label><input id="pGoal" value="${esc(state.profile?.goal||state.onboarding.goal||'퍼포먼스 향상')}"></div></div><button id="saveProfile" class="primary" style="margin-top:12px">저장</button></section>
<section class="card"><h3>운영 상태</h3><div class="metric-row"><span>Cloud</span><b>${currentUser&&firebaseReady?'Firebase 연결':'로컬 모드'}</b></div><div class="metric-row"><span>Schema</span><b>v${SCHEMA_VERSION}</b></div><div class="metric-row"><span>오류 로그</span><b>${state.errors.length}</b></div><div class="metric-row"><span>Action Log</span><b>${state.actionLog.length}</b></div><div class="actions" style="margin-top:10px"><button id="retrySync" class="ghost">동기화 재시도</button><button id="exportData" class="ghost">데이터 내보내기</button></div></section></div>
<div class="section-title"><h2>사용자 모델</h2></div><section class="card"><div class="metric-row"><span>목표</span><b>${esc(state.onboarding.goal)}</b></div><div class="metric-row"><span>경험</span><b>${esc(state.onboarding.experience)}</b></div><div class="metric-row"><span>주간 횟수</span><b>${state.onboarding.weeklyFrequency}회</b></div><div class="metric-row"><span>가능 시간</span><b>${state.onboarding.availableMinutes}분</b></div><div class="actions" style="margin-top:10px"><button class="ghost" data-pagego="onboarding">온보딩 다시 설정</button><button id="importLegacy" class="ghost">구버전 로컬 데이터 가져오기</button></div></section>`;}
function onboardingPage(){return `${pageHead('START / 사용자 모델','GARANG이 먼저 알아야 할 것','입력값은 나중에 언제든 수정할 수 있으며 건너뛸 수 있습니다.')}
<section class="card" style="max-width:720px;margin:auto"><div class="form-grid"><div class="field full"><label>주요 목표</label><select id="oGoal"><option ${state.onboarding.goal==='근육 증가'?'selected':''}>근육 증가</option><option ${state.onboarding.goal==='체지방 감소'?'selected':''}>체지방 감소</option><option ${state.onboarding.goal==='러닝 퍼포먼스'?'selected':''}>러닝 퍼포먼스</option><option ${state.onboarding.goal==='퍼포먼스 향상'?'selected':''}>퍼포먼스 향상</option><option ${state.onboarding.goal==='전반적인 건강'?'selected':''}>전반적인 건강</option></select></div><div class="field"><label>운동 경험</label><select id="oExperience"><option value="beginner">입문</option><option value="intermediate" ${state.onboarding.experience==='intermediate'?'selected':''}>중급</option><option value="advanced" ${state.onboarding.experience==='advanced'?'selected':''}>숙련</option></select></div><div class="field"><label>주간 가능 횟수</label><input id="oFrequency" type="number" min="1" max="7" value="${state.onboarding.weeklyFrequency}"></div><div class="field"><label>하루 가능 시간</label><input id="oMinutes" type="number" min="10" max="240" value="${state.onboarding.availableMinutes}"></div><div class="field full"><label>운동 선호 / 제약</label><textarea id="oPreferences" rows="4" placeholder="예: 저녁 운동 선호, 무릎 충격 큰 동작은 피하고 싶음">${esc(state.onboarding.preferences)}</textarea></div></div><div class="actions" style="margin-top:14px"><button id="saveOnboarding" class="primary">GARANG 시작</button><button id="skipOnboarding" class="ghost">나중에 설정</button></div></section>`;}

const pages={today:todayPage,coach:coachPage,log:logPage,progress:progressPage,workout:workoutPage,nutrition:nutritionPage,running:runningPage,body:bodyPage,planner:plannerPage,memory:memoryPage,profile:profilePage,onboarding:onboardingPage};

function bindPage(){
  document.querySelectorAll('[data-pagego]').forEach(b=>b.onclick=()=>go(b.dataset.pagego));
  document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{go('coach');const q=$('aiQuestion');if(q){q.value=b.dataset.q;askAI();}});
  document.querySelectorAll('[data-action="open-checkin"]').forEach(b=>b.onclick=openCheckinModal);
  document.querySelectorAll('[data-action="apply-coach-plan"]').forEach(b=>b.onclick=applyCoachPlan);
  document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{progressRangeDays=num(b.dataset.range,30);render();});
  if(currentPage==='workout')bindWorkout();
  if(currentPage==='nutrition')bindNutrition();
  if(currentPage==='running')bindRunning();
  if(currentPage==='body')$('saveBody').onclick=saveBody;
  if(currentPage==='coach')$('askAI').onclick=askAI;
  if(currentPage==='planner')bindPlanner();
  if(currentPage==='memory')bindMemory();
  if(currentPage==='profile')bindProfile();
  if(currentPage==='onboarding')bindOnboarding();
}

function openCheckinModal(){const c=latestCheckin()||{sleep:7,energy:3,stress:3,soreness:2,availableMinutes:state.onboarding.availableMinutes||60,soreArea:''};const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<div class="modal"><div class="modal-head"><div><span class="eyebrow">TODAY CHECK-IN</span><h2>오늘의 상태</h2></div><button class="modal-close" type="button">×</button></div><div class="checkin-form"><div class="field"><label>수면 시간</label><input id="ciSleep" type="number" min="0" max="14" step="0.5" value="${c.sleep}"></div>${rangeField('에너지','ciEnergy',c.energy)}${rangeField('스트레스','ciStress',c.stress)}${rangeField('근육통','ciSoreness',c.soreness)}<div class="field"><label>근육통 부위 (선택)</label><input id="ciSoreArea" value="${esc(c.soreArea||'')}" placeholder="예: 대퇴사두근"></div><div class="field"><label>오늘 가능한 시간 (분)</label><input id="ciMinutes" type="number" min="10" max="240" value="${c.availableMinutes}"></div><button id="saveCheckin" class="primary wide">상태 저장</button></div></div>`;document.body.appendChild(wrap);wrap.querySelector('.modal-close').onclick=()=>wrap.remove();wrap.onclick=e=>{if(e.target===wrap)wrap.remove();};wrap.querySelectorAll('input[type=range]').forEach(r=>r.oninput=()=>{r.parentElement.querySelector('output').value=r.value;});$('saveCheckin').onclick=()=>{const x={id:c.id||uid(),date:today(),sleep:num($('ciSleep').value,7),energy:num($('ciEnergy').value,3),stress:num($('ciStress').value,3),soreness:num($('ciSoreness').value,2),soreArea:$('ciSoreArea').value.trim(),availableMinutes:num($('ciMinutes').value,state.onboarding.availableMinutes||60),updatedAt:isoNow()};state.checkins=state.checkins.filter(v=>v.date!==today());state.checkins.push(x);saveState({event:'checkin_saved',source:'today'});wrap.remove();toast('오늘 상태를 저장했습니다.');render();};}
function rangeField(label,id,value){return `<div class="range-row"><label for="${id}">${label}</label><input id="${id}" type="range" min="1" max="5" value="${value}"><output>${value}</output></div>`;}

function localCoachSummary(d,s){return `GARANG Coach Engine V1\n\n오늘 결정: ${d.decision}\n${d.summary}\n\n${d.reasons.map(x=>`• ${x}`).join('\n')}\n\nGARANG Score: ${s.total??'기준선 생성 중'}${SERVICES.coachEndpoint?'\n\n외부 AI Gateway가 연결되어 있습니다.':'\n\n현재 외부 LLM 미연결 상태입니다. 위 내용은 실제 기록을 사용하는 로컬 규칙 엔진 분석입니다.'}`;}
function buildContext(){return {profile:state.profile,onboarding:state.onboarding,today:{date:today(),checkin:latestCheckin(),planner:todayPlans(),meals:dayMeals(),mealTotals:totalsMeals(),workouts:todayWorkouts(),body:latestBody()},recent:{workouts:state.workouts.slice(-20),runs:state.runs.slice(-15),body:state.body.slice(-15)},memory:state.memory.entries.filter(x=>x.userConfirmed||num(x.importance)>=3).slice(-40),performance:performanceScore(),coachDecision:coachDecision()};}
async function askAI(){const q=$('aiQuestion')?.value.trim();if(!q)return toast('질문을 입력해 주세요.');const out=$('aiAnswer');out.textContent='GARANG이 기록을 확인하고 있습니다…';trackEvent('ai_chat_started',{provider:SERVICES.coachEndpoint?'gateway':'local'});if(SERVICES.coachEndpoint){try{const r=await fetch(SERVICES.coachEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:q,context:buildContext()})});if(!r.ok)throw new Error(`AI Gateway ${r.status}`);const data=await r.json();out.textContent=data.answer||data.output||'AI Gateway 응답 형식을 확인해 주세요.';return;}catch(e){captureError('coach_gateway',e);out.textContent=`외부 AI 연결에 실패했습니다. 가짜 응답으로 대체하지 않고 로컬 Coach Engine 분석을 표시합니다.\n\n${generateLocalAnswer(q)}`;return;}}out.textContent=generateLocalAnswer(q);}
function generateLocalAnswer(q){const lower=q.toLowerCase(),d=coachDecision(),t=totalsMeals(),last=state.workouts.at(-1);if(/식단|단백질|먹|영양/.test(lower)){const gap=Math.max(0,proteinTarget()-t.protein);return `로컬 Coach Engine V1 분석\n오늘 단백질 ${Math.round(t.protein)}g / 목표 약 ${proteinTarget()}g입니다. ${Math.round(gap)}g 정도 여유가 있습니다. 오늘 섭취는 ${Math.round(t.kcal)} kcal입니다. 사진 자동 인식은 Vision API 연결 전까지 실제 인식했다고 표시하지 않습니다.`;}if(/운동|강도|오늘|회복|상태/.test(lower))return localCoachSummary(d,performanceScore());if(/최근|기록/.test(lower))return `로컬 Coach Engine V1 분석\n운동 ${state.workouts.length}개, 식사 ${state.meals.length}개, 러닝 ${state.runs.length}개, Body ${state.body.length}개 기록을 현재 사용자 Context로 보고 있습니다.${last?` 최근 운동은 ${last.name} ${last.weight}kg × ${last.reps} × ${last.sets}세트입니다.`:''}`;return `외부 LLM은 현재 연결되지 않았습니다. GARANG의 실제 데이터 기반 규칙 엔진으로 답할 수 있는 범위는 운동 강도, 오늘 상태, 식단 목표, 최근 기록 분석입니다.`;}

function applyCoachPlan(){const d=coachDecision();const time=todayPlans()[0]?.time||'18:30';const message=`오늘 ${time}에 “${d.title}” 계획을 추가할까요?\n\n${d.summary}`;if(!window.confirm(message))return;const p={id:uid(),date:today(),time,type:d.decision==='RECOVER'||d.decision==='REST'?'recovery':'workout',title:d.title,source:'ai',status:'confirmed',completed:false,reason:d.summary,createdAt:isoNow(),updatedAt:isoNow()};state.planner.push(p);state.actionLog.push({id:uid(),action:'create_plan',targetId:p.id,reason:d.summary,userConfirmed:true,sourceData:['checkin','workout_history','planner'],at:isoNow()});saveState({event:'ai_plan_applied',source:'coach'});toast('사용자 승인 후 Planner에 적용했습니다.');render();}

function exerciseFor(name){const q=String(name||'').trim().toLowerCase();return db.exercise.find(x=>String(x.exercise_name||'').toLowerCase()===q)||db.exercise.find(x=>String(x.exercise_name||'').toLowerCase().includes(q));}
function calcWorkoutKcal({duration,body,rpe,met}){const base=num(met,5),intensity=1+Math.max(0,Math.min(10,num(rpe,7))-7)*.04;return Math.max(1,Math.round(base*intensity*3.5*body/200*duration));}
function buildWorkout(){const name=$('wName').value.trim();if(!name){toast('운동 종목을 입력해 주세요.');return null;}const ref=exerciseFor(name),sets=Math.max(1,num($('wSets').value,1)),reps=Math.max(1,num($('wReps').value,1)),weight=Math.max(0,num($('wWeight').value)),rpe=clamp(num($('wRpe').value,8),1,10),duration=Math.max(1,num($('wDuration').value,15)),body=Math.max(1,num($('wBody').value,state.profile?.weight||67)),met=num(ref?.met_default,5);return {id:uid(),name,sets,reps,weight,rpe,duration,body,met,kcal:calcWorkoutKcal({duration,body,rpe,met}),volume:sets*reps*weight};}
function bindWorkout(){$('addWorkout').onclick=()=>{const x=buildWorkout();if(x){workoutDraft.push(x);toast(`${x.name} 추가`);render();}};$('clearWorkoutDraft').onclick=()=>{workoutDraft=[];render();};$('saveWorkoutSession').onclick=saveWorkoutSession;$('certWorkout').onclick=()=>pickMedia('mediaPicker',m=>{currentCert.workout=m;showCert('workoutCertArea',m,state.workouts.at(-1),'workout');});document.querySelectorAll('[data-remove-workout]').forEach(b=>b.onclick=()=>{workoutDraft.splice(num(b.dataset.removeWorkout),1);render();});document.querySelectorAll('[data-edit-workout]').forEach(b=>b.onclick=()=>editWorkout(num(b.dataset.editWorkout)));}
function editWorkout(i){const x=workoutDraft[i];if(!x)return;$('wName').value=x.name;$('wSets').value=x.sets;$('wReps').value=x.reps;$('wWeight').value=x.weight;$('wRpe').value=x.rpe;$('wDuration').value=x.duration;$('wBody').value=x.body;workoutDraft.splice(i,1);toast('수정 후 다시 세션에 추가해 주세요.');}
function saveWorkoutSession(){if(!workoutDraft.length)return toast('운동을 먼저 추가해 주세요.');const sessionId=uid();workoutDraft.forEach(x=>state.workouts.push({...x,date:today(),sessionId}));state.memory.events.push({type:'workout_session',date:today(),text:`${workoutDraft.length}종목`});workoutDraft=[];saveState({event:'workout_saved',source:'workout'});toast('운동 세션을 저장했습니다.');render();}

function findFood(q){q=String(q||'').trim().toLowerCase();if(!q)return null;return db.food.find(x=>String(x.name||'').toLowerCase()===q)||db.food.find(x=>(x.aliases||[]).some(a=>String(a).toLowerCase()===q))||db.food.find(x=>String(x.name||'').toLowerCase().includes(q));}
function foodItem(name,grams){const f=findFood(name);if(!f)return null;const g=Math.max(1,num(grams,100)),ratio=g/num(f.basis_g,100);return {id:uid(),name:f.name,grams:g,kcal:num(f.kcal)*ratio,protein:num(f.protein)*ratio,carbs:num(f.carbs)*ratio,fat:num(f.fat)*ratio};}
function fillFood(manual=true){const f=findFood($('foodSearch').value);if(!f){if(manual)toast('Food DB에서 찾지 못했습니다.');return;}const x=foodItem(f.name,$('foodGram').value);$('foodKcal').value=Math.round(x.kcal);$('foodProtein').value=x.protein.toFixed(1);$('foodCarb').value=x.carbs.toFixed(1);$('foodFat').value=x.fat.toFixed(1);}
function bindNutrition(){
  $('foodSearch').addEventListener('input',()=>fillFood(false));$('fillFood').onclick=()=>fillFood(true);$('addFood').onclick=addMealDraft;$('saveMeal').onclick=saveMealGroup;
  document.querySelectorAll('[data-remove-food]').forEach(b=>b.onclick=()=>{mealDraft.splice(num(b.dataset.removeFood),1);render();});document.querySelectorAll('[data-edit-food]').forEach(b=>b.onclick=()=>editMeal(num(b.dataset.editFood)));
  $('pickMealScan').onclick=()=>pickMedia('mealScanPicker',m=>{if(mealScanDraft?.url)URL.revokeObjectURL(mealScanDraft.url);mealScanDraft={...m,manualName:'',grams:100,items:[]};render();});$('clearMealScan').onclick=()=>{if(mealScanDraft?.url)URL.revokeObjectURL(mealScanDraft.url);mealScanDraft=null;render();};$('analyzeMealScan').onclick=analyzeMealScan;$('confirmMealScan')?.addEventListener('click',()=>{mealDraft.push(...mealScanDraft.items.map(x=>({...x,id:uid()})));toast('분석 초안을 식사에 추가했습니다. 저장 전 수정할 수 있습니다.');mealScanDraft.items=[];render();});
}
function addMealDraft(){const name=$('foodSearch').value.trim();if(!name)return toast('음식을 입력해 주세요.');const f=findFood(name),g=Math.max(1,num($('foodGram').value,100));const x=f?foodItem(f.name,g):{id:uid(),name,grams:g,kcal:num($('foodKcal').value),protein:num($('foodProtein').value),carbs:num($('foodCarb').value),fat:num($('foodFat').value)};if(!f&&!x.kcal&&!x.protein&&!x.carbs&&!x.fat)return toast('영양성분을 입력하거나 DB에서 불러와 주세요.');mealDraft.push(x);toast(`${x.name} 추가`);render();}
function editMeal(i){const x=mealDraft[i];if(!x)return;$('foodSearch').value=x.name;$('foodGram').value=x.grams;$('foodKcal').value=Math.round(x.kcal);$('foodProtein').value=x.protein.toFixed(1);$('foodCarb').value=x.carbs.toFixed(1);$('foodFat').value=x.fat.toFixed(1);mealDraft.splice(i,1);toast('수정 후 다시 추가해 주세요.');}
function saveMealGroup(){if(!mealDraft.length)return toast('음식을 먼저 추가해 주세요.');const totals=mealDraft.reduce((a,x)=>({kcal:a.kcal+x.kcal,protein:a.protein+x.protein,carbs:a.carbs+x.carbs,fat:a.fat+x.fat}),{kcal:0,protein:0,carbs:0,fat:0});const meal={id:uid(),date:today(),name:mealDraft.map(x=>x.name).slice(0,2).join(' + ')+(mealDraft.length>2?` 외 ${mealDraft.length-2}종`:''),items:mealDraft.map(x=>({...x})),...totals};state.meals.push(meal);state.memory.events.push({type:'meal',date:today(),text:`${meal.items.length}종 · ${Math.round(meal.kcal)} kcal`});mealDraft=[];saveState({event:'meal_saved',source:'nutrition'});toast('식사를 저장했습니다.');render();}
async function analyzeMealScan(){if(!mealScanDraft?.file)return toast('먼저 음식 사진을 선택해 주세요.');mealScanDraft.manualName=$('scanFoodName').value.trim();mealScanDraft.grams=Math.max(1,num($('scanFoodGram').value,100));if(SERVICES.mealScanEndpoint){try{toast('사진을 분석 중입니다.');const fd=new FormData();fd.append('image',mealScanDraft.file);fd.append('userId',currentUser?.uid||'demo');const r=await fetch(SERVICES.mealScanEndpoint,{method:'POST',body:fd});if(!r.ok)throw new Error(`Meal Scan ${r.status}`);const data=await r.json();if(!Array.isArray(data.items)||!data.items.length)throw new Error('Meal Scan response has no items');mealScanDraft.items=data.items.map(i=>({id:uid(),name:String(i.name||'음식'),grams:num(i.grams,100),kcal:num(i.kcal),protein:num(i.protein),carbs:num(i.carbs),fat:num(i.fat)}));trackEvent('meal_scan_draft_created',{provider:'vision'});render();return;}catch(e){captureError('meal_scan',e);toast('Vision 분석에 실패했습니다. 임의 결과를 만들지 않습니다.');return;}}
  if(!mealScanDraft.manualName)return toast('Vision API 미연결 상태입니다. 음식명을 입력하면 DB 기반 초안을 만들 수 있습니다.');const x=foodItem(mealScanDraft.manualName,mealScanDraft.grams);if(!x)return toast('Food DB에서 해당 음식을 찾지 못했습니다. 직접 입력을 사용해 주세요.');mealScanDraft.items=[x];trackEvent('meal_scan_draft_created',{provider:'local_db'});render();}

function bindRunning(){$('runStart').onclick=startRun;$('runStop').onclick=stopRun;$('runCert').onclick=()=>pickMedia('mediaPicker',m=>{currentCert.running=m;showCert('runCertArea',m,state.runs.at(-1),'running');});}
function startRun(){if(runState)return toast('이미 러닝 중입니다.');if(!navigator.geolocation)return toast('이 기기에서는 GPS를 사용할 수 없습니다.');runState={started:Date.now(),distance:0,coords:[],watchId:null};$('gpsStatus').textContent='GPS 연결 중…';runState.watchId=navigator.geolocation.watchPosition(pos=>{const p=pos.coords;runState.coords.push([p.latitude,p.longitude,pos.timestamp]);if(runState.coords.length>1){const a=runState.coords.at(-2),b=runState.coords.at(-1);runState.distance+=haversine(a[0],a[1],b[0],b[1]);}updateRoute();updateRunUI();$('gpsStatus').textContent=`GPS 연결 · 정확도 ${Math.round(p.accuracy)}m`;},()=>{$('gpsStatus').textContent='GPS 권한 또는 신호를 확인해 주세요.';},{enableHighAccuracy:true,maximumAge:1000,timeout:10000});runTimer=setInterval(updateRunUI,1000);trackEvent('run_started');}
function updateRunUI(){if(!runState)return;const sec=Math.floor((Date.now()-runState.started)/1000),min=Math.floor(sec/60),s=String(sec%60).padStart(2,'0');if($('runDistance'))$('runDistance').textContent=runState.distance.toFixed(2);if($('runTime'))$('runTime').textContent=`${String(min).padStart(2,'0')}:${s}`;if($('runPace'))$('runPace').textContent=runState.distance>0?(sec/60/runState.distance).toFixed(2):'—';}
function updateRoute(){const line=$('routeLine');if(!line||!runState?.coords.length)return;const pts=runState.coords;if(pts.length<2){line.setAttribute('points','50,50');return;}const lats=pts.map(p=>p[0]),lons=pts.map(p=>p[1]),minLat=Math.min(...lats),maxLat=Math.max(...lats),minLon=Math.min(...lons),maxLon=Math.max(...lons),dLat=maxLat-minLat||1e-6,dLon=maxLon-minLon||1e-6;line.setAttribute('points',pts.map(p=>`${8+84*(p[1]-minLon)/dLon},${92-84*(p[0]-minLat)/dLat}`).join(' '));}
function stopRun(){if(!runState)return toast('진행 중인 러닝이 없습니다.');if(runState.watchId!=null)navigator.geolocation.clearWatch(runState.watchId);clearInterval(runTimer);const sec=Math.max(1,Math.floor((Date.now()-runState.started)/1000)),duration=sec/60,d=runState.distance,pace=d?duration/d:0,body=num(state.profile?.weight,67),kcal=Math.round(d*body*1.036);state.runs.push({id:uid(),date:today(),distance:d,duration,pace:pace?pace.toFixed(2):'—',kcal,coords:runState.coords});runState=null;saveState({event:'run_saved',source:'running'});toast('러닝을 저장했습니다.');render();}
function haversine(a,b,c,d){const R=6371,rad=Math.PI/180,da=(c-a)*rad,db=(d-b)*rad,x=Math.sin(da/2)**2+Math.cos(a*rad)*Math.cos(c*rad)*Math.sin(db/2)**2;return 2*R*Math.asin(Math.sqrt(x));}

function saveBody(){const weight=num($('bWeight').value),height=num($('bHeight').value||state.profile?.height),fatPct=num($('bFatPct').value),fatMass=num($('bFatMass').value)||(weight&&fatPct?weight*fatPct/100:0),muscle=num($('bMuscle').value);if(!weight)return toast('체중을 입력해 주세요.');const bmi=height?weight/Math.pow(height/100,2):0;const age=num(state.profile?.age,30);const bmr=height?Math.round(10*weight+6.25*height-5*age+5):0;state.body.push({id:uid(),date:$('bDate').value||today(),weight:Number(weight.toFixed(1)),muscle:muscle?Number(muscle.toFixed(1)):null,fatPercent:fatPct?Number(fatPct.toFixed(1)):null,fatMass:fatMass?Number(fatMass.toFixed(1)):null,bmi:bmi?Number(bmi.toFixed(1)):null,bmr:bmr||null,source:'manual',userConfirmed:true});state.profile={...(state.profile||{}),weight,height:height||state.profile?.height};saveState({event:'inbody_saved',source:'body'});toast('체성분을 저장했습니다.');render();}

function filterProgress(days){return {workouts:state.workouts.filter(x=>withinDays(x.date,days)),meals:state.meals.filter(x=>withinDays(x.date,days)),runs:state.runs.filter(x=>withinDays(x.date,days)),body:state.body.filter(x=>withinDays(x.date,days)),checkins:state.checkins.filter(x=>withinDays(x.date,days))};}
function sparkline(values){if(values.length<2)return '';const min=Math.min(...values),max=Math.max(...values),range=max-min||1;const points=values.map((v,i)=>`${(i/(values.length-1))*100},${86-((v-min)/range)*70}`).join(' ');return `<svg class="spark" viewBox="0 0 100 92" preserveAspectRatio="none"><line class="gridline" x1="0" y1="86" x2="100" y2="86"/><line class="gridline" x1="0" y1="16" x2="100" y2="16"/><polyline points="${points}"/></svg><div class="muted">${values[0].toFixed(1)}kg → ${values.at(-1).toFixed(1)}kg</div>`;}

function bindPlanner(){$('addPlan').onclick=()=>{const title=$('planTitle').value.trim();if(!title)return toast('계획 내용을 입력해 주세요.');state.planner.push({id:uid(),date:$('planDate').value||today(),time:$('planTime').value||'',type:$('planType').value,title,source:'user',status:'confirmed',completed:false,createdAt:isoNow(),updatedAt:isoNow()});saveState({event:'planner_created',source:'planner'});toast('계획을 저장했습니다.');render();};document.querySelectorAll('[data-plan-toggle]').forEach(b=>b.onclick=()=>{const p=state.planner.find(x=>x.id===b.dataset.planToggle);if(p){p.completed=!p.completed;p.updatedAt=isoNow();saveState({event:'planner_completed',source:'planner'});render();}});document.querySelectorAll('[data-plan-delete]').forEach(b=>b.onclick=()=>{if(!confirm('이 계획을 삭제할까요?'))return;state.planner=state.planner.filter(x=>x.id!==b.dataset.planDelete);saveState({event:'planner_deleted'});render();});}

function bindMemory(){const editing=state.memory.entries.find(x=>x.id===memoryEditId);if(editing){$('memType').value=editing.type;$('memImportance').value=editing.importance;$('memKey').value=editing.key;$('memValue').value=editing.value;}$('saveMemory').onclick=()=>{const key=$('memKey').value.trim(),value=$('memValue').value.trim();if(!key||!value)return toast('Key와 내용을 입력해 주세요.');if(memoryEditId){const m=state.memory.entries.find(x=>x.id===memoryEditId);Object.assign(m,{type:$('memType').value,key,value,importance:clamp(num($('memImportance').value,3),1,5),updatedAt:isoNow()});state.actionLog.push({id:uid(),action:'update_memory',targetId:m.id,userConfirmed:true,at:isoNow()});memoryEditId=null;}else{const m={id:uid(),type:$('memType').value,key,value,source:'user',confidence:1,importance:clamp(num($('memImportance').value,3),1,5),userConfirmed:true,createdAt:isoNow(),updatedAt:isoNow(),expiresAt:null};state.memory.entries.push(m);state.actionLog.push({id:uid(),action:'save_memory',targetId:m.id,userConfirmed:true,at:isoNow()});}saveState({event:'memory_saved',source:'memory'});toast('Memory를 저장했습니다.');render();};$('cancelMemoryEdit')?.addEventListener('click',()=>{memoryEditId=null;render();});document.querySelectorAll('[data-memory-confirm]').forEach(b=>b.onclick=()=>{const m=state.memory.entries.find(x=>x.id===b.dataset.memoryConfirm);if(m){m.userConfirmed=!m.userConfirmed;m.updatedAt=isoNow();saveState({event:'memory_confirmed'});render();}});document.querySelectorAll('[data-memory-edit]').forEach(b=>b.onclick=()=>{memoryEditId=b.dataset.memoryEdit;render();});document.querySelectorAll('[data-memory-delete]').forEach(b=>b.onclick=()=>{if(!confirm('이 Memory를 삭제할까요?'))return;state.memory.entries=state.memory.entries.filter(x=>x.id!==b.dataset.memoryDelete);saveState({event:'memory_deleted'});render();});}

function bindProfile(){$('saveProfile').onclick=()=>{state.profile={...(state.profile||{}),name:$('pName').value.trim()||'GARANG 사용자',age:num($('pAge').value),height:num($('pHeight').value),weight:num($('pWeight').value),goal:$('pGoal').value.trim()||'퍼포먼스 향상'};state.onboarding.goal=state.profile.goal;saveState({event:'profile_updated'});toast('프로필을 저장했습니다.');render();};$('retrySync').onclick=()=>{if(currentUser&&firebaseReady)cloudSaveNow().then(ok=>toast(ok?'동기화가 완료되었습니다.':'동기화 설정을 확인해 주세요.'));else toast('로그인 상태에서 클라우드 동기화를 사용할 수 있습니다.');};$('exportData').onclick=exportData;$('importLegacy').onclick=importLegacy;}
function bindOnboarding(){$('saveOnboarding').onclick=()=>{state.onboarding={...state.onboarding,complete:true,skipped:false,goal:$('oGoal').value,experience:$('oExperience').value,weeklyFrequency:clamp(num($('oFrequency').value,4),1,7),availableMinutes:clamp(num($('oMinutes').value,60),10,240),preferences:$('oPreferences').value.trim()};state.profile={...(state.profile||{}),goal:state.onboarding.goal};saveState({event:'onboarding_completed'});toast('사용자 모델을 저장했습니다.');go('today');};$('skipOnboarding').onclick=()=>{state.onboarding.skipped=true;saveState({event:'onboarding_skipped'});go('today');};}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`GARANG_DATA_${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);trackEvent('data_exported');}
function importLegacy(){const old=readLocal(LEGACY_KEY);if(!old)return toast('구버전 로컬 데이터를 찾지 못했습니다.');if(!confirm('구버전 로컬 데이터를 현재 계정/데모 상태로 가져올까요? 현재 데이터와 병합됩니다.'))return;const keep=clone(state);state={...keep,...old,workouts:[...(keep.workouts||[]),...(old.workouts||[])],meals:[...(keep.meals||[]),...(old.meals||[])],runs:[...(keep.runs||[]),...(old.runs||[])],body:[...(keep.body||[]),...(old.body||[])]};normalizeState();saveState({event:'legacy_imported'});toast('구버전 데이터를 병합했습니다.');render();}

function pickMedia(inputId,cb){const input=$(inputId);input.value='';input.onchange=()=>{const f=input.files?.[0];if(!f)return;cb({url:URL.createObjectURL(f),type:f.type,name:f.name,file:f});};input.click();}
function certInfo(record,kind){const r=record||{};return kind==='running'?{title:'RUN VERIFIED',main:`${num(r.distance).toFixed(2)} KM`,meta:`${num(r.duration).toFixed(1)} MIN · ${r.pace||'—'} /KM · ${r.date||today()}`}:{title:'WORKOUT VERIFIED',main:`${r.name||'WORKOUT'} · ${r.weight||0} KG`,meta:`${r.sets||0} SETS · ${r.reps||0} REPS · RPE ${r.rpe||'—'} · ${r.date||today()}`};}
function showCert(id,m,record,kind){const area=$(id);if(!area)return;const isVideo=m.type.startsWith('video'),info=certInfo(record,kind);area.className='cert';area.innerHTML=`<div class="cert-media"><${isVideo?'video':'img'} src="${m.url}" ${isVideo?'controls muted playsinline':''} alt="GARANG 인증 미디어"><div class="cert-overlay-pro"><div class="overlay-top"><div class="overlay-brand"><img src="garang-mark.svg" alt=""><span>GARANG</span></div><span class="verified-chip">VERIFIED</span></div><div class="overlay-bottom"><span class="overlay-kicker">${info.title}</span><strong>${esc(info.main)}</strong><span class="overlay-meta">${esc(info.meta)}</span></div></div></div><div class="cert-controls"><button class="primary small" id="certShare">공유 / 저장</button></div>`;$('certShare').onclick=()=>shareMedia(m);}
async function shareMedia(m){try{if(navigator.share&&m.file&&navigator.canShare?.({files:[m.file]})){await navigator.share({title:'GARANG VERIFIED',files:[m.file]});return;}const a=document.createElement('a');a.href=m.url;a.download=m.name;a.target='_blank';a.click();}catch(e){if(e?.name!=='AbortError')toast('공유/저장이 브라우저 정책으로 제한됩니다.');}}

async function registerSW(){if('serviceWorker'in navigator)try{await navigator.serviceWorker.register('./sw.js');}catch(e){captureError('service_worker',e);}}
async function boot(){storageKey=localStorage.getItem('garang_demo')==='1'?DEMO_KEY:DEMO_KEY;loadLocal(storageKey);await loadDB();bindAuth();nav();initFirebase();registerSW();if(localStorage.getItem('garang_demo')==='1'&&!firebaseReady)showApp();else if(!firebaseReady)showAuth();}
boot();
})();
